import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import Layout from '../components/Layout';
import { performancePages } from '../websitePerformanceContent';

const formatScore = (score) => {
  if (typeof score !== 'number') return 'N/A';
  return Math.round(score * 100);
};

const scoreLabel = (score) => {
  const value = formatScore(score);
  if (value === 'N/A') return 'Not available';
  if (value >= 90) return 'Good';
  if (value >= 50) return 'Needs improvement';
  return 'Poor';
};

const getAuditValue = (audits, key) => audits?.[key]?.displayValue || 'N/A';

const normalizeUrl = (value) => {
  const trimmed = value.trim();
  if (!trimmed) return '';
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
};

export default function WebsitePerformance() {
  const [websiteUrl, setWebsiteUrl] = useState('');
  const [strategy, setStrategy] = useState('mobile');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);

  useEffect(() => {
    document.title = 'Website Speed Test & Performance Guides | Speed Pings';
    const meta = document.querySelector('meta[name="description"]');
    if (meta) {
      meta.setAttribute(
        'content',
        'Test website speed and learn Core Web Vitals, PageSpeed Insights, GTmetrix and website speed optimization with Speed Pings.'
      );
    }
  }, []);

  const summary = useMemo(() => {
    if (!result) return null;

    const lighthouse = result.lighthouseResult;
    const categories = lighthouse?.categories || {};
    const audits = lighthouse?.audits || {};

    return {
      finalUrl: lighthouse?.finalDisplayedUrl || result.id || websiteUrl,
      fetchedAt: result.analysisUTCTimestamp,
      performance: categories.performance?.score,
      seo: categories.seo?.score,
      accessibility: categories.accessibility?.score,
      bestPractices: categories['best-practices']?.score,
      metrics: [
        { label: 'First Contentful Paint', value: getAuditValue(audits, 'first-contentful-paint') },
        { label: 'Largest Contentful Paint', value: getAuditValue(audits, 'largest-contentful-paint') },
        { label: 'Speed Index', value: getAuditValue(audits, 'speed-index') },
        { label: 'Total Blocking Time', value: getAuditValue(audits, 'total-blocking-time') },
        { label: 'Cumulative Layout Shift', value: getAuditValue(audits, 'cumulative-layout-shift') },
        { label: 'Time to Interactive', value: getAuditValue(audits, 'interactive') },
      ],
      opportunities: Object.values(audits)
        .filter((audit) => audit?.details?.type === 'opportunity' && typeof audit.score === 'number' && audit.score < 0.9)
        .sort((a, b) => (b.numericValue || 0) - (a.numericValue || 0))
        .slice(0, 5)
        .map((audit) => ({
          title: audit.title,
          value: audit.displayValue || 'Review recommended',
        })),
    };
  }, [result, websiteUrl]);

  const handleSubmit = async (event) => {
    event.preventDefault();

    const normalizedUrl = normalizeUrl(websiteUrl);

    if (!normalizedUrl) {
      setError('Please enter a website URL.');
      return;
    }

    try {
      new URL(normalizedUrl);
    } catch (urlError) {
      setError('Please enter a valid URL, for example https://speedpings.com');
      return;
    }

    setLoading(true);
    setError('');
    setResult(null);

    try {
      const apiUrl = new URL('https://www.googleapis.com/pagespeedonline/v5/runPagespeed');
      apiUrl.searchParams.set('url', normalizedUrl);
      apiUrl.searchParams.set('strategy', strategy);
      apiUrl.searchParams.append('category', 'performance');
      apiUrl.searchParams.append('category', 'seo');
      apiUrl.searchParams.append('category', 'accessibility');
      apiUrl.searchParams.append('category', 'best-practices');

      const response = await fetch(apiUrl.toString());
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.error?.message || 'Unable to test this website right now.');
      }

      setResult(data);
    } catch (fetchError) {
      setError(fetchError.message || 'Website performance test failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Layout>
      <main className="page-hero">
        <section className="page-title">
          <span className="hero-kicker">Website Performance</span>
          <h1>Website Speed Test, Core Web Vitals and Page Speed Guides</h1>
          <p>
            Test a website URL, review performance details and learn how to improve Core Web Vitals,
            Google PageSpeed Insights scores, GTmetrix reports, mobile website speed and user experience.
          </p>
        </section>

        <section className="website-test-panel" aria-labelledby="website-speed-test-title">
          <div className="website-test-copy">
            <span className="hero-kicker">Website Speed Test</span>
            <h2 id="website-speed-test-title">Check website performance by URL</h2>
            <p>
              Enter any public website URL to check performance score, SEO score, accessibility,
              best practices and key speed metrics like LCP, CLS, Speed Index and Total Blocking Time.
            </p>
          </div>

          <form className="website-test-form" onSubmit={handleSubmit}>
            <label htmlFor="website-url">Website URL</label>
            <div className="website-search-row">
              <input
                id="website-url"
                type="url"
                value={websiteUrl}
                onChange={(event) => setWebsiteUrl(event.target.value)}
                placeholder="https://example.com"
                inputMode="url"
              />
              <button type="submit" className="run-btn" disabled={loading}>
                {loading ? 'Testing...' : 'Search'}
              </button>
            </div>

            <div className="strategy-toggle" aria-label="Test strategy">
              <button
                type="button"
                className={strategy === 'mobile' ? 'active' : ''}
                onClick={() => setStrategy('mobile')}
              >
                Mobile
              </button>
              <button
                type="button"
                className={strategy === 'desktop' ? 'active' : ''}
                onClick={() => setStrategy('desktop')}
              >
                Desktop
              </button>
            </div>

            <p className="form-note">
              Results use Google PageSpeed Insights data. Public pages work best; private, blocked or
              localhost URLs may not return results.
            </p>
          </form>
        </section>

        {error && <div className="website-test-error">{error}</div>}

        {summary && (
          <section className="website-results" aria-live="polite">
            <div className="results-header">
              <div>
                <span className="hero-kicker">Performance Result</span>
                <h2>{summary.finalUrl}</h2>
                <p>{summary.fetchedAt ? `Checked at ${new Date(summary.fetchedAt).toLocaleString()}` : 'Latest test result'}</p>
              </div>
              <strong className="strategy-badge">{strategy}</strong>
            </div>

            <div className="score-grid">
              <div className="score-card">
                <span>Performance</span>
                <strong>{formatScore(summary.performance)}</strong>
                <p>{scoreLabel(summary.performance)}</p>
              </div>
              <div className="score-card">
                <span>SEO</span>
                <strong>{formatScore(summary.seo)}</strong>
                <p>{scoreLabel(summary.seo)}</p>
              </div>
              <div className="score-card">
                <span>Accessibility</span>
                <strong>{formatScore(summary.accessibility)}</strong>
                <p>{scoreLabel(summary.accessibility)}</p>
              </div>
              <div className="score-card">
                <span>Best Practices</span>
                <strong>{formatScore(summary.bestPractices)}</strong>
                <p>{scoreLabel(summary.bestPractices)}</p>
              </div>
            </div>

            <div className="metrics-grid">
              {summary.metrics.map((metric) => (
                <div key={metric.label}>
                  <span>{metric.label}</span>
                  <strong>{metric.value}</strong>
                </div>
              ))}
            </div>

            <div className="opportunity-box">
              <h3>Top Optimization Opportunities</h3>
              {summary.opportunities.length > 0 ? (
                <ul>
                  {summary.opportunities.map((item) => (
                    <li key={item.title}>
                      <strong>{item.title}</strong>
                      <span>{item.value}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p>No major optimization opportunities were reported for this test.</p>
              )}
            </div>
          </section>
        )}

        <section className="legal-container seo-section">
          <h2>Website Speed Learning Center</h2>
          <p>
            This section is for website owners, developers, bloggers, SEO professionals and marketers who want
            to understand page speed, Core Web Vitals, website speed test reports and practical optimization steps.
            For checking your internet connection speed, use the Speed Pings home page.
          </p>
        </section>

        <section className="article-grid">
          {performancePages.map((page) => (
            <Link className="article-card" key={page.slug} to={`/website-performance/${page.slug}`}>
              <div className="article-visual performance-icon" aria-hidden="true">{page.icon}</div>
              <h2>{page.title}</h2>
              <p>{page.description}</p>
              <strong>Read guide →</strong>
            </Link>
          ))}
        </section>
      </main>
    </Layout>
  );
}
